CREATE TABLE dim_customer_scd (customer_id INTEGER, city VARCHAR, valid_from DATE, valid_to DATE);
INSERT INTO dim_customer_scd VALUES
    (1042, 'Казань', '2025-01-01', '2026-03-14'),
    (1042, 'Москва', '2026-03-15', '9999-12-31');

WITH sample_orders(order_id, customer_id, order_date) AS (
    VALUES (1, 1042, DATE '2025-11-02'), (2, 1042, DATE '2026-03-15'), (3, 1042, DATE '2026-06-01')
)
SELECT s.order_id, s.order_date, d.city
FROM sample_orders s
JOIN dim_customer_scd d
  ON d.customer_id = s.customer_id
 AND s.order_date BETWEEN d.valid_from AND d.valid_to
ORDER BY s.order_id;
